/* Hand-authored pilot: one continuous learning journey, not a generated expansion. */
(function(){'use strict';
const ID='projectile-focus-1',VERSION='2026.10.12-projectile-pilot',G=9.8;
const existing=window.Year12PhysicsLessons?.[ID];if(!existing)throw Error('Projectile pilot source missing');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const math=(eq,note='')=>'<div class="pp-equation">'+eq+(note?'<small>'+note+'</small>':'')+'</div>';
const note=(label,text,tone='blue')=>'<aside class="pp-note '+tone+'"><b>'+label+'</b><p>'+text+'</p></aside>';
const pair=(a,b)=>'<div class="pp-pair"><section>'+a+'</section><section>'+b+'</section></div>';
const steps=items=>'<ol class="pp-working">'+items.map(([heading,body])=>'<li><b>'+heading+'</b><div>'+body+'</div></li>').join('')+'</ol>';
const paper=(label)=>'<label class="pp-written">'+label+'<textarea data-pp-draft="'+esc(label)+'" rows="4" placeholder="Use paper or write your reasoning here."></textarea></label>';
const reveal=(title,body)=>'<details class="pp-reveal"><summary>'+title+'</summary>'+body+'</details>';
const PHOTO='<figure class="pp-photo"><img src="assets/physics/lesson-photos/projectile-basketball.webp" width="1000" height="667" alt="A basketball in flight just above a hoop" loading="eager" decoding="async"><figcaption>A shot looks like one motion. We will describe it using two directions.<details><summary>Photo credit</summary>Noah Silliman / <a href="https://unsplash.com/photos/time-lapse-photography-of-ball-about-to-shoot-on-basketball-hoop-EcTL3VkgId4" target="_blank" rel="noopener">Unsplash</a></details></figcaption></figure>';
let graphic=0;
function svg(label,body,h=400){const id='pp-arrow-'+(++graphic);return '<figure class="pp-diagram"><div class="pp-diagram-viewport"><svg class="pp-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 '+h+'" role="img" aria-label="'+esc(label)+'"><title>'+esc(label)+'</title><defs><marker id="'+id+'" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="context-stroke"/></marker></defs>'+body.replaceAll('ARROW',id)+'</svg></div><figcaption><button type="button" class="pp-diagram-zoom" data-pp-zoom aria-label="Enlarge '+esc(label)+'">Enlarge diagram ↗</button></figcaption></figure>';}
const text=(x,y,s,color='#18374d',anchor='start')=>'<text x="'+x+'" y="'+y+'" fill="'+color+'" text-anchor="'+anchor+'" font-family="Arial,sans-serif" font-size="19">'+esc(s)+'</text>';
const line=(x,y,a,b,color='#526d82',dash=false)=>'<path d="M'+x+' '+y+'L'+a+' '+b+'" stroke="'+color+'" stroke-width="3" fill="none"'+(dash?' stroke-dasharray="6 6"':'')+'/>';
const arrow=(x,y,a,b,color='#0b8774')=>'<path d="M'+x+' '+y+'L'+a+' '+b+'" stroke="'+color+'" stroke-width="4" fill="none" marker-end="url(#ARROW)"/>';
const ball=(x,y,r=10,color='#e48d2a')=>'<circle cx="'+x+'" cy="'+y+'" r="'+r+'" fill="'+color+'" stroke="#18374d" stroke-width="2"/>';
function flight(u,angle,g=G,height=0){const rad=angle*Math.PI/180,ux=u*Math.cos(rad),uy=u*Math.sin(rad),time=(uy+Math.sqrt(uy*uy+2*g*height))/g;return {ux,uy,time,range:ux*time,peak:uy*uy/(2*g),at:t=>({x:ux*t,y:uy*t-.5*g*t*t,vx:ux,vy:uy-g*t})};}
function curve(f,toX,toY){return Array.from({length:81},(_,i)=>{const p=f.at(f.time*i/80);return(i?'L':'M')+toX(p.x).toFixed(2)+' '+toY(p.y).toFixed(2)}).join(' ');}
function components(u=10,angle=30){const r=angle*Math.PI/180,scale=34,ox=145,oy=310,x=ox+u*Math.cos(r)*scale,y=oy-u*Math.sin(r)*scale;return svg('Velocity triangle: resultant u, horizontal component ux, vertical component uy and angle to horizontal',arrow(ox,oy,x,oy,'#0b8774')+arrow(x,oy,x,y,'#2a6bb2')+arrow(ox,oy,x,y,'#c87518')+'<path d="M'+(x-18)+' '+oy+'V'+(oy-18)+'H'+x+'" fill="none" stroke="#526d82" stroke-width="2"/><path d="M'+(ox+60)+' '+oy+'A60 60 0 0 0 '+(ox+60*Math.cos(r))+' '+(oy-60*Math.sin(r))+'" fill="none" stroke="#c87518" stroke-width="2"/>'+text(220,289,'θ = '+angle+'°')+text((ox+x)/2,355,'ux: horizontal', '#0b8774','middle')+text(x+20,(oy+y)/2,'uy: vertical','#2a6bb2')+text(175,150,'u: launch velocity','#a05910')+text(75,35,'One velocity. Two perpendicular components.')+text(75,385,'Angle θ is measured from the horizontal. Schematic triangle.'));}
function forces(){return svg('Free-body diagram after release: the only modelled force is weight downward',ball(350,140,35)+arrow(350,175,350,300,'#c87518')+text(405,155,'ball after release')+text(375,260,'weight: W = mg','#a05910')+text(75,45,'FORCES ON THE BALL')+text(75,365,'No hand force after release. Air resistance is neglected.'));}
function axes(){const f=flight(10,30),s=58,ox=90,oy=310;return svg('Launch point is the origin; positive x is right, positive y is up',arrow(ox,oy,680,oy,'#0b8774')+arrow(ox,oy,ox,70,'#2a6bb2')+'<path d="'+curve(f,x=>ox+x*s,y=>oy-y*s)+'" stroke="#c87518" stroke-width="4" fill="none"/>'+ball(ox,oy)+text(105,345,'launch: x = 0, y = 0')+text(585,345,'+x (right)','#0b8774')+text(105,75,'+y (up)','#2a6bb2')+text(405,180,'positive y: above launch')+text(405,385,'below launch → negative y'));}
function snapshots(){const ox=90,oy=90,s=60;let b=arrow(75,90,650,90,'#0b8774')+arrow(75,90,75,25,'#2a6bb2');for(let i=0;i<=5;i++){const t=i*.2,x=ox+6*t*s,y=oy+.5*G*t*t*s;b+=ball(x,y,10)+text(x+15,y+24,t.toFixed(1)+' s');}b+=line(90,55,162,55)+line(162,55,234,55)+[90,162,234].map(x=>line(x,49,x,61)).join('')+text(290,50,'equal horizontal gaps: 1.20 m')+text(115,445,'Vertical gaps grow: the downward speed is increasing.')+text(95,480,'uₓ = 6.00 m/s; uᵧ = 0; snapshots every 0.20 s.');return svg('Equal-time snapshots have equal horizontal gaps and increasing downward gaps',b,515);}
function dropScene(t=.5){const sy=48,dy=.5*G*t*t*sy,y=80+dy,x=340+3*t*sy;return svg('Dropped and horizontally launched balls have the same height at the same time',line(90,329.2,665,329.2)+line(90,80,210,80)+line(295,80,405,80)+ball(150,y,14,'#2a6bb2')+ball(x,y,14,'#0b8774')+line(150,y,x,y,'#526d82',true)+text(90,45,'Dropped: uₓ = 0','#2a6bb2')+text(335,45,'Launched: uₓ = 3.00 m/s','#0b8774')+text(100,350,'Same launch height; both uᵧ = 0; same g.')+text(260,395,'time = '+t.toFixed(2)+' s')+text(530,135,'Same y at')+text(530,163,'the same time.'),430);}
function xMotion(){let b=line(75,225,700,225);for(let i=0;i<3;i++){let x=120+i*225;b+=ball(x,225)+arrow(x,210,x+105,210,'#0b8774')+text(x,278,['0 s','0.50 s','1.00 s'][i],'#18374d','middle');}return svg('Horizontal projection with equal velocity arrows at equal time intervals',b+text(70,45,'HORIZONTAL PROJECTION — not the complete path')+text(70,95,'vₓ = uₓ = 8.66 m/s throughout','#0b8774')+text(70,350,'aₓ = 0: no horizontal resultant force in this model.'));}
function apex(){const f=flight(10,30),s=59,ox=85,oy=310,t=f.uy/G,p=f.at(t),x=ox+p.x*s,y=oy-p.y*s;return svg('At the apex: horizontal velocity remains nonzero, vertical velocity is zero and acceleration is downward',line(65,310,690,310)+'<path d="'+curve(f,x=>ox+x*s,y=>oy-y*s)+'" stroke="#b9c7d2" stroke-width="4" fill="none"/>'+ball(x,y,14)+arrow(x+18,y,x+155,y,'#0b8774')+arrow(x,y+20,x,y+120,'#c87518')+text(x+40,y-25,'vₓ = 8.66 m/s','#0b8774')+text(x+35,y+60,'aᵧ = −9.80 m/s²','#a05910')+text(75,95,'At the top: vᵧ = 0')+text(75,395,'The ball has not stopped. Only its vertical velocity is zero.'),430);}
function yTerms(){return svg('Signed contributions to vertical displacement at 0.40 seconds',line(270,45,270,340,'#9aadb9',true)+arrow(270,100,570,100,'#2a6bb2')+arrow(270,200,152.4,200,'#c87518')+arrow(270,300,452.4,300,'#0b8774')+text(25,100,'launch term')+text(25,200,'gravity term')+text(25,300,'net Δy')+text(365,85,'+2.00 m','#2a6bb2')+text(315,185,'−0.784 m','#a05910')+text(485,305,'+1.216 m','#0b8774')+text(80,375,'These are signed terms in y, not force arrows.'));}
function cliff(height=15,distance=281,moon=true){const ox=110,oy=95,endx=650,endy=315;let path=Array.from({length:51},(_,i)=>{const f=i/50;return(i?'L':'M')+(ox+(endx-ox)*f).toFixed(2)+' '+(oy+(endy-oy)*f*f).toFixed(2)}).join(' ');return svg('Horizontal launch with labelled vertical drop and horizontal displacement',line(55,oy,ox,oy)+line(ox,oy,ox,endy)+line(55,endy,700,endy)+'<path d="'+path+'" stroke="#c87518" stroke-width="4" fill="none"/>'+ball(ox,oy)+ball(endx,endy)+arrow(ox+15,oy,ox+145,oy,'#0b8774')+arrow(75,oy,75,endy,'#2a6bb2')+line(ox,355,endx,355)+text(175,65,'uₓ = ?; uᵧ = 0')+text(135,205,'Δy = −'+Number(height).toFixed(moon?1:2)+' m','#2a6bb2')+text(345,382,'Δx = +'+Number(distance).toFixed(moon?0:1)+' m','#0b8774','middle')+text(450,45,moon?'Moon: g = 1.62 m/s²':'Earth: g = 9.80 m/s²')+text(95,425,'Axes: +x right, +y up. Schematic, not to scale.'),450);}
function compareAngles(){const a=flight(10,30),b=flight(10,60),s=58,ox=85,oy=315;return svg('Equal-speed launches at 30 and 60 degrees share a range but have different heights and flight times',line(65,oy,710,oy)+'<path d="'+curve(a,x=>ox+x*s,y=>oy-y*s)+'" fill="none" stroke="#0b8774" stroke-width="4"/><path d="'+curve(b,x=>ox+x*s,y=>oy-y*s)+'" fill="none" stroke="#2a6bb2" stroke-width="4"/>'+text(70,40,'Same speed: 10.0 m/s; same launch and landing height')+text(405,355,'60°: taller, longer flight','#2a6bb2')+text(70,355,'30°: flatter, shorter flight','#0b8774')+text(155,405,'Both ranges ≈ 8.84 m. Equal x and y scales.'),440);}
function check(key,q,options,correct,reasons){return '<fieldset class="pp-check" data-pp-choice="'+esc(key)+'" data-correct="'+correct+'"><legend>'+q+'</legend>'+options.map((o,i)=>'<label><input type="radio" name="pp-'+esc(key)+'" value="'+i+'"> <span>'+o+'</span></label>').join('')+'<button type="button" class="pp-button" data-pp-check>Check my reasoning</button><p class="pp-feedback" role="status" aria-live="polite"></p>'+reasons.map((r,i)=>'<template data-reason="'+i+'">'+r+'</template>').join('')+'</fieldset>';}
function number(key,q,value,unit,why,tol=.025){return '<div class="pp-number" data-pp-number="'+esc(key)+'" data-answer="'+value+'" data-tolerance="'+tol+'"><label>'+q+'<span class="pp-number-entry"><input type="number" step="any" inputmode="decimal" aria-label="'+esc(q)+'"> <b>'+unit+'</b></span></label><button class="pp-button" type="button" data-pp-number-check>Check</button><p class="pp-feedback" role="status" aria-live="polite"></p><template>'+why+'</template></div>';}
function sim(mode='launch'){return '<div class="pp-sim" data-pp-sim="'+mode+'"><div class="pp-sim-controls">'+(mode==='launch'?'<label>Launch speed <input data-pp-u type="range" min="6" max="20" step="1" value="10"><output data-pp-u-label>10 m/s</output></label><label>Launch angle <input data-pp-angle type="range" min="15" max="75" step="5" value="30"><output data-pp-angle-label>30°</output></label>':'<label>Gravity <select data-pp-g><option value="9.8">Earth: 9.80 m/s²</option><option value="1.62">Moon: 1.62 m/s²</option></select></label>')+'<label>Time through flight <input data-pp-time type="range" min="0" max="100" step="1" value="0"><output data-pp-time-label>0.00 s</output></label></div><div data-pp-scene></div><div class="pp-sim-readout" aria-live="polite"></div><p class="pp-caption">Drag the time control. This is a calculated model; air resistance is neglected.</p></div>';}
const pages=[];
function page(chapter,title,body,type='learn'){pages.push({chapter,title,html:'<div class="pp-page">'+body+'</div>',type});}
page(0,'Why does the ball bend?', '<p class="pp-lead">Once the ball leaves the player’s hand, what keeps changing its path?</p>'+PHOTO+check('hook','Choose the best explanation.',['The hand continues pushing the ball.','Gravity acts after release.','The ball runs out of horizontal force.'],1,['Contact with the hand has ended. The hand set the launch velocity, but its force no longer acts on the ball.','Yes. Gravity keeps changing the vertical velocity. We will see why the horizontal motion behaves differently.','Motion does not need a continuing force. A resultant force is needed to change velocity.']),'interactive');
page(0,'Try the motion before the maths','<p>Keep the speed at <b>10 m/s</b>. Compare <b>30°</b> and <b>60°</b>, then drag the time control for each shot.</p>'+sim()+note('Look for two things','The ball travels to the right while its height changes. At the highest point it still moves sideways.')+paper('What changed when you increased the launch angle?'),'interactive');
page(0,'What counts as a projectile?', '<p>A <b>projectile</b> is an object moving under gravity after launch, with air resistance neglected in our ideal model.</p>'+pair('<h3>Included in this model</h3><p>A thrown ball after release. A golf ball after it leaves the club. An object dropped from a ledge.</p>','<h3>Needs a different model</h3><p>A rocket while its engine provides thrust. A ball while a hand is still pushing it.</p>')+check('projectile','Which object is described by gravity alone in the ideal model?',['A rocket with its engine firing.','A ball after it has left the hand.','A ball being pushed upward by a hand.'],1,['Engine thrust is another force; the gravity-only model is incomplete.','Correct. Contact with the launcher has ended, and we are explicitly neglecting air resistance.','Contact force from the hand must still be included.']),'interactive');
page(0,'Draw the forces after release',forces()+'<p>Weight is the gravitational force: <b>W = mg</b>, where m is mass in kilograms and g is gravitational acceleration. In our near-Earth model, g = 9.80 m/s².</p>'+note('Separate force from velocity','The ball can move right while its only force points down. A velocity arrow tells you how it moves; a force arrow tells you what changes its velocity.','amber')+paper('Sketch the ball after release and draw only the force acting on it.'));
page(0,'Choose an origin and signs',axes()+pair('<h3>Horizontal: x</h3><p>Right is positive. Δx tells us how far to the right of launch the ball has moved.</p>','<h3>Vertical: y</h3><p>Up is positive. Below the launch point, Δy is negative. This is not automatically height above the ground.</p>')+note('Keep this convention','We use +x right and +y up throughout this lesson. Therefore aᵧ = −g.'));
page(0,'One ball, two components',pair('<h3 class="pp-x">Horizontal motion</h3><p>Track how its x-position changes. Without air resistance, its horizontal velocity does not change.</p>','<h3 class="pp-y">Vertical motion</h3><p>Track how its y-position changes. Gravity changes its vertical velocity.</p>')+math('same object → same elapsed time <b>t</b>','Never use one flight time for x and a different flight time for y.')+note('Independent does not mean unrelated','The two equations describe different directions, but they describe the same start and end events.'));
page(0,'Read equal-time snapshots',snapshots()+check('snapshots','Why do the horizontal gaps stay equal while vertical gaps grow?',['Horizontal velocity is constant; downward velocity changes.','Gravity acts only at the last dot.','The ball gains horizontal velocity.'],0,['Correct. Equal times × equal horizontal velocity give equal horizontal displacements. Gravity increases the downward speed.','Gravity acts throughout the flight, including at the earliest dot.','Growing horizontal velocity would produce growing horizontal gaps; the diagram shows equal gaps.']),'interactive');
page(0,'Dropped or launched: which lands first?', '<p>Two balls start at the same height with <b>zero initial vertical velocity</b>. One is dropped; the other is launched horizontally.</p><div class="pp-drop" data-pp-drop><label>Time <input data-pp-drop-time type="range" min="0" max="1" value="0" step="0.01"></label><div data-pp-drop-scene>'+dropScene(0)+'</div></div>'+check('drop','With air resistance neglected, which reaches the ground first?',['The dropped ball.','The horizontally launched ball.','They land together.'],2,['Both have the same vertical starting conditions and acceleration. Moving sideways does not shorten the vertical fall.','Moving sideways does not add vertical hang time. The vertical starting conditions are the same.','Correct. Their y-motion is identical. Their x-motion differs, but both use the same elapsed time.']),'interactive');
page(1,'Turn the launch arrow into components',components()+note('What the triangle represents','u is the launch speed with direction θ. uₓ and uᵧ are the horizontal and vertical parts of that same velocity. They are not extra velocities to add on top of u.'));
page(1,'Why cosine here and sine there?',components().replace('u: launch velocity','hypotenuse: u').replace('ux: horizontal','adjacent: uₓ').replace('uy: vertical','opposite: uᵧ')+pair('<h3 class="pp-x">Adjacent to θ: horizontal</h3>'+math('cos θ = uₓ / u<br>uₓ = u cos θ')+'<p>Multiply both sides by u to isolate the horizontal component.</p>','<h3 class="pp-y">Opposite θ: vertical</h3>'+math('sin θ = uᵧ / u<br>uᵧ = u sin θ')+'<p>Multiply both sides by u to isolate the vertical component.</p>')+note('Read the angle first','These forms use θ measured from the horizontal. An angle measured from the vertical changes which side is adjacent.','amber'));
page(1,'Worked launch: 10.0 m/s at 30.0°',steps([['Identify the given quantities','The launch speed is u = 10.0 m/s. The angle is 30.0° above the horizontal. Use degree mode.'],['Find the horizontal component',math('uₓ = 10.0 × cos 30.0°<br>= 10.0 × 0.866025…<br>= 8.66025… m/s')+'Cosine selects the adjacent side of the triangle.'],['Find the vertical component',math('uᵧ = 10.0 × sin 30.0°<br>= 10.0 × 0.500<br>= 5.00 m/s')+'Sine selects the opposite side.'],['Check the result','Both components are smaller than 10.0 m/s. √(8.66025² + 5.00²) = 10.0 m/s reconstructs the original magnitude. Keep guard digits for later steps.']]),'worked');
page(1,'Your turn: resolve a steeper launch','<p>A ball is launched at <b>20.0 m/s, 60.0° above horizontal</b>. Draw the component triangle before calculating.</p>'+number('ux60','Horizontal component uₓ',10,'m/s','uₓ = 20.0 cos 60.0° = 10.0 m/s. The horizontal side is adjacent to the stated angle.',.06)+number('uy60','Vertical component uᵧ',17.320508,'m/s','uᵧ = 20.0 sin 60.0° = 17.3 m/s. Sine selects the opposite side. Swapping your two answers usually means the angle reference was swapped.',.08),'practice');
page(1,'Check the limiting angles',pair('<h3>0°: horizontal launch</h3>'+math('uₓ = u cos 0° = u<br>uᵧ = u sin 0° = 0')+'<p>All the initial velocity is horizontal. The ball begins gaining downward velocity immediately after release.</p>','<h3>90°: vertical launch</h3>'+math('uₓ = u cos 90° = 0<br>uᵧ = u sin 90° = u')+'<p>There is no horizontal displacement in this model.</p>')+check('zero','A horizontal launch means which quantity is initially zero?',['The entire launch velocity.','Only the vertical component uᵧ.','Gravitational acceleration.'],1,['It still has horizontal velocity; setting u = 0 would describe a drop from rest.','Correct. Horizontal launch fixes uᵧ = 0, while uₓ can be nonzero.','Gravity acts after release even when the initial vertical velocity is zero.']),'interactive');
page(2,'Horizontal motion: no mystery force',xMotion()+math('aₓ = 0 → vₓ = uₓ<br>Δx = uₓt')+'<p>Displacement is constant horizontal velocity multiplied by elapsed time.</p>'+note('Units explain the operation','(m/s) × s = m. For uₓ = 8.66 m/s and t = 0.400 s, Δx = 3.464 m.'));
page(2,'Vertical velocity changes every second',math('vᵧ = uᵧ + aᵧt<br>vᵧ = uᵧ − gt')+'<p>With up positive, gravity subtracts <b>9.80 m/s from vᵧ each second</b> near Earth.</p>'+steps([['Example: start with uᵧ = +5.00 m/s','After 0.200 s, vᵧ = 5.00 − (9.80)(0.200) = +3.04 m/s. It is still moving up, but more slowly.'],['After 0.800 s','vᵧ = 5.00 − (9.80)(0.800) = −2.84 m/s. It is now moving down.']])+note('A negative velocity is a direction','It does not automatically mean slowing down. While vᵧ and aᵧ are both negative, downward speed increases.','amber'));
page(2,'Vertical displacement: why the one-half?', '<p>For constant vertical acceleration, displacement is <b>average vertical velocity × time</b>.</p>'+math('average vᵧ = (uᵧ + vᵧ)/2<br>= (uᵧ + uᵧ − gt)/2<br>= uᵧ − ½gt')+math('Δy = average vᵧ × t<br>Δy = uᵧt − ½gt²')+yTerms()+note('Two contributions','At t = 0.400 s with uᵧ = 5.00 m/s: launch term = +2.00 m; gravity term = −0.784 m; Δy = +1.216 m.'));
page(2,'At the highest point, what is zero?',apex()+check('apex','Which statement is correct at the apex of the 10.0 m/s, 30° launch?',['All velocity and acceleration are zero.','vᵧ = 0, but vₓ is nonzero and aᵧ = −g.','Gravity switches off until the ball falls.'],1,['Only the vertical component of velocity reaches zero. Horizontal motion and gravity continue.','Correct. The vertical motion reverses at that instant, while horizontal motion continues and gravity remains downward.','Gravity acts continuously. If it switched off, the vertical velocity would not become negative afterward.']),'interactive');
page(2,'Combine the directions at one instant', '<p>Use the <b>10.0 m/s, 30.0°</b> launch. At <b>t = 0.400 s</b>, find its displacement from the launch point.</p>'+number('instant-x','Horizontal displacement Δx',3.4641016,'m','Δx = uₓt = (10 cos 30°)(0.400) = 3.46 m. Use the horizontal component, not the full 10.0 m/s.',.035)+number('instant-y','Vertical displacement Δy',1.216,'m','Δy = uᵧt − ½gt² = (5.00)(0.400) − ½(9.80)(0.400)² = +1.216 m. Square the whole time value.',.025)+reveal('Read the position as a sentence','<p>The ball is approximately <b>3.46 m to the right</b> and <b>1.22 m above</b> its launch point. Both values describe the same instant.</p>'),'practice');
const examQ='An astronaut on the Moon hits a golf ball horizontally into a crater. The ball lands 15.0 m below its launch height, having travelled 281 m horizontally. Calculate the horizontal launch velocity. (5 marks)';
page(3,'A real exam question: the Moon shot','<p class="pp-source">West Australian Test Papers · 2024 · Units 3/4 · Question 1</p><blockquote class="pp-question">'+examQ+'</blockquote><p>Use lunar g = <b>1.62 m/s²</b>. Our +y direction remains upward.</p>'+cliff()+paper('Before seeing the solution: label the known quantities and the unknown.'),'practice');
page(3,'Plan before touching the calculator',pair('<h3 class="pp-x">Horizontal information</h3><p>Δx = +281 m<br>uₓ = ?<br>aₓ = 0</p>','<h3 class="pp-y">Vertical information</h3><p>Δy = −15.0 m<br>uᵧ = 0<br>aᵧ = −1.62 m/s²</p>')+steps([['Find the shared time from the fall','The vertical displacement, initial vertical velocity and acceleration are all known. The vertical equation can therefore give t.'],['Then find horizontal speed','Use that same t with Δx = uₓt.']])+note('The key decision','“Horizontally” means uᵧ = 0. It does not mean the ball’s launch speed is zero.','amber'));
page(3,'Work the fall time, including the algebra',steps([['Choose the vertical displacement equation',math('Δy = uᵧt + ½aᵧt²')+'This contains the known drop and unknown time, without needing the horizontal speed.'],['Substitute with consistent signs',math('−15.0 = 0 × t + ½(−1.62)t²<br>−15.0 = −0.810t²')+'Both vertical displacement and acceleration are negative because up is positive.'],['Isolate t², then undo the square',math('t² = (−15.0)/(−0.810)<br>= 18.5185… s²<br>t = √(18.5185…) = 4.30331… s')+'A time-squared result is not yet a time. Use the positive square root for the later landing event.']])+note('Calculator entry','√(2 × 15.0 ÷ 1.62) gives the same positive time. Retain 4.30331… for the next step.'),'worked');
page(3,'Use the time to find launch speed',steps([['Start with the horizontal relationship',math('Δx = uₓt')+'Horizontal acceleration is zero, so this same uₓ applies throughout the flight.'],['Make the unknown the subject',math('uₓ = Δx/t')+'Divide both sides by the complete time; do not multiply distance by time.'],['Substitute, then report the result',math('uₓ = 281 ÷ 4.30331…<br>= 65.298… m/s<br>≈ 65.3 m/s to the right')+'The units m ÷ s are velocity units. About 65 m each second for 4.3 s gives about 280 m: the size is plausible.']])+reveal('How the five practice marking points connect to the method','<ol><li>Correct vertical starting quantities, including uᵧ = 0. [1]</li><li>Appropriate constant-acceleration relationship. [1]</li><li>Correct time, approximately 4.30 s. [1]</li><li>Horizontal velocity = horizontal displacement/time. [1]</li><li>Correct value with unit, approximately 65.3 m/s. [1]</li></ol><p>This is explained working for the imported source question. Equivalent correct sign conventions also give the same result.</p>'),'worked');
page(3,'Spot a convincing-looking mistake','<p>A student writes: <b>“Launch speed = 281 ÷ 15.0 = 18.7 m/s.”</b></p>'+check('ratio','Why is that method invalid?',['The distance numbers are too large.','It divides horizontal distance by vertical distance, not by time.','The answer needs more decimal places.'],1,['Large distances can be valid. The problem is which physical quantities were combined.','Exactly. Metres divided by metres gives a dimensionless ratio. First use the vertical fall to find seconds, then divide horizontal metres by those seconds.','Rounding cannot repair a relationship with the wrong physical meaning.'])+paper('Write the two-stage method you would use to correct this answer.'),'interactive');
page(4,'Guided practice: a platform launch','<p>A ball leaves a platform <b>horizontally</b> and lands <b>4.90 m below launch</b>, <b>12.0 m away horizontally</b>. Use g = 9.80 m/s².</p>'+cliff(4.9,12,false)+reveal('Hint 1: start with the vertical direction',math('−4.90 = 0 × t − ½(9.80)t²')+'<p>Divide by −4.90 to obtain t², then take the positive square root.</p>')+number('guided-t','Flight time',1,'s','t² = 1.00 s², so t = 1.00 s. The horizontal distance was not needed to find the time.',.012)+reveal('Hint 2: use the same time horizontally',math('uₓ = Δx/t = 12.0/1.00'))+number('guided-u','Horizontal launch speed',12,'m/s','uₓ = 12.0 m/s. Keeping the directions separate made the problem solvable.',.08),'practice');
page(4,'Independent practice: show a complete method','<p>A ball is launched horizontally. It lands <b>19.6 m below its launch point</b> after travelling <b>30.0 m horizontally</b>. Use g = 9.80 m/s².</p><p><b>Calculate the flight time and horizontal launch speed. [5 marks]</b> Draw a labelled diagram and show your equations before checking.</p>'+paper('Independent horizontal-launch working')+number('ind-t','Your flight time',2,'s','Vertical motion gives t = √(2 × 19.6/9.80) = 2.00 s. Horizontal velocity does not determine this fall time.',.025)+number('ind-u','Your horizontal launch speed',15,'m/s','uₓ = 30.0/2.00 = 15.0 m/s. Include direction or clearly identify it as horizontal speed.',.1)+reveal('Self-mark your written method: 5 points',steps([['Correct vertical quantities [1]','Δy = −19.6 m; uᵧ = 0; aᵧ = −9.80 m/s².'],['Appropriate equation [1]',math('Δy = uᵧt + ½aᵧt²')],['Time [1]',math('−19.6 = −4.90t² → t = 2.00 s')],['Horizontal relationship [1]',math('uₓ = Δx/t')],['Speed and unit [1]',math('uₓ = 15.0 m/s')]])),'practice');
page(4,'Independent practice: an angled launch','<p>A ball launches at <b>20.0 m/s, 60.0° above horizontal</b>. At <b>0.500 s</b>, calculate Δx, Δy and vᵧ. Use g = 9.80 m/s².</p>'+paper('Angled-launch working: include the initial components')+number('angled-x','Horizontal displacement Δx',5,'m','uₓ = 20 cos 60° = 10.0 m/s, then Δx = 10.0 × 0.500 = 5.00 m.',.03)+number('angled-y','Vertical displacement Δy',7.435254,'m','uᵧ = 20 sin 60° = 17.3205… m/s. Δy = (17.3205…)(0.500) − ½(9.80)(0.500)² = 7.44 m.',.04)+number('angled-vy','Vertical velocity vᵧ',12.420508,'m/s','vᵧ = 17.3205… − (9.80)(0.500) = +12.4 m/s. The positive sign says the ball is still moving upward.',.08)+reveal('Suggested marking: 6 points','<ol><li>Correct initial components. [1]</li><li>Correct horizontal relationship. [1]</li><li>Δx = 5.00 m with unit. [1]</li><li>Correct vertical displacement relationship and substitution. [1]</li><li>Δy ≈ +7.44 m with unit. [1]</li><li>vᵧ ≈ +12.4 m/s, including upward interpretation. [1]</li></ol>'),'practice');
page(4,'Returning to the launch height','<p>When a projectile returns to its <b>launch height</b>, its vertical displacement is zero. Use this to find its complete flight time.</p>'+steps([['Set the event, not just the formula',math('0 = uᵧt − ½gt²')+'The landing event has Δy = 0. This does not describe a landing below launch.'],['Factor the equation',math('0 = t(uᵧ − ½gt)')+'One root is t = 0: the launch event itself. The later return needs the other factor to be zero.'],['Solve for the later event',math('uᵧ − ½gt = 0<br>T = 2uᵧ/g')+'For uᵧ = 5.00 m/s, T = 1.02041… s. Use Δx = uₓT to find the range.']])+note('Keep the condition attached','T = 2uᵧ/g applies here because launch and landing heights are equal, and vertical acceleration is constant.','amber'),'worked');
page(4,'Same range does not mean the same motion',compareAngles()+pair('<h3 class="pp-x">30° launch</h3><p>uₓ = 8.66 m/s<br>uᵧ = 5.00 m/s<br>T ≈ 1.02 s<br>range ≈ 8.84 m</p>','<h3 class="pp-y">60° launch</h3><p>uₓ = 5.00 m/s<br>uᵧ = 8.66 m/s<br>T ≈ 1.77 s<br>range ≈ 8.84 m</p>')+'<p>The steeper launch has less horizontal speed but more flight time. Their product is the same in this equal-height, no-drag example.</p>'+check('same-range','Which comparison is correct?',['They have the same range, height and flight time.','They have the same range but different maximum heights and flight times.','The 60° launch has a greater horizontal component.'],1,['Their ranges match, but the higher initial vertical component gives the 60° launch greater height and flight time.','Correct. Equal range can come from different combinations of horizontal speed and flight time.','For the same launch speed, cos 60° is smaller than cos 30°, so its horizontal component is smaller.']),'interactive');
page(4,'Can this shot reach the hoop?','<p>A ball launches at <b>10.0 m/s, 30.0° above horizontal</b>. The hoop is <b>8.00 m to the right</b> and <b>2.00 m above the launch point</b>. Ignore ball size and air resistance.</p><p>Find the ball’s height relative to launch <b>when it reaches the hoop’s horizontal position</b>. Will it reach the hoop?</p>'+paper('Hoop challenge: decide which direction gives time first')+reveal('A hint that changes the order','<p>This time the target x-position is known. Find t = Δx/uₓ first, then substitute that same time into Δy = uᵧt − ½gt².</p>')+number('hoop-y','Vertical displacement at x = 8.00 m',.43746882,'m','t = 8.00/(10 cos 30°) = 0.923760… s. Δy = (5.00)t − 4.90t² = +0.437 m. That is below the required +2.00 m, so this ideal shot is too low.',.025)+note('The important skill','Choose the direction that has enough information to find time. The Moon shot used y first; the hoop problem uses x first.'),'practice');
page(4,'Change the planet; keep the launch the same','<p>Here a ball launches horizontally at <b>20.0 m/s</b> from <b>15.0 m above the landing surface</b>. Compare Earth and Moon gravity.</p>'+sim('planet')+check('gravity','With height and horizontal launch speed fixed, smaller g gives…',['Less flight time and a shorter range.','More flight time and a longer range.','The same time because horizontal speed is unchanged.'],1,['The fall is less strongly accelerated, so it takes longer to reach the landing surface.','Correct. t = √(2H/g) increases as g decreases, and range = uₓt then increases.','The time is determined by the vertical fall. Constant horizontal speed does not fix that fall time.']),'interactive');
page(4,'Know when the model needs changing',pair('<h3>Air resistance or wind</h3><p>Horizontal velocity may change. Then aₓ = 0 and Δx = uₓt may no longer be appropriate.</p>','<h3>Different landing height</h3><p>The general vertical equation still works for constant g, but the equal-height shortcut T = 2uᵧ/g does not.</p>')+check('limits','A ball lands below its launch point. Which is the reliable starting relationship?',['Always use T = 2uᵧ/g.','Use the actual signed Δy in Δy = uᵧt − ½gt².','Set vertical displacement to zero.'],1,['That shortcut assumes equal start and finish heights. Its assumption has changed.','Correct. Describe the actual landing event using its displacement from launch.','Below launch means negative Δy with our upward-positive convention; it is not zero.']),'interactive');
page(4,'Your compact problem-solving reference', '<div class="pp-reference">'+pair('<h3 class="pp-x">Horizontal</h3><p>uₓ = u cos θ<br>aₓ = 0<br>vₓ = uₓ<br>Δx = uₓt</p>','<h3 class="pp-y">Vertical</h3><p>uᵧ = u sin θ<br>aᵧ = −g<br>vᵧ = uᵧ − gt<br>Δy = uᵧt − ½gt²</p>')+'</div><ol class="pp-summary"><li><b>Define the event:</b> where does the interval start and finish?</li><li><b>Draw and label:</b> axes, initial components, displacement and acceleration.</li><li><b>Find the shared time:</b> start with whichever direction has enough known information.</li><li><b>Use the other direction:</b> apply the same elapsed time.</li><li><b>Interpret:</b> units, signs, model assumptions and whether the size is plausible.</li></ol><p>Next, use the separate mastery check. Your written calculations still need self-review or teacher marking.</p>');
const bank=[
 {q:'After an ideal projectile leaves the hand, its modelled force is…',o:['a forward force from the hand','weight downward','a force in the direction of velocity','no force'],a:1,explain:'Hand contact has ended. In the gravity-only model weight acts downward throughout flight.'},
 {q:'A horizontal launch at 12 m/s has initial vertical velocity…',o:['12 m/s','−9.8 m/s','0 m/s','unknown in every case'],a:2,explain:'“Horizontal launch” fixes uᵧ = 0. It does not set the nonzero horizontal component to zero.'},
 {q:'Two balls start at the same height with uᵧ = 0. One has more horizontal speed. With no drag, the fall times are…',o:['equal','longer for the faster ball','shorter for the faster ball','set by total launch speed'],a:0,explain:'The vertical starting conditions and g are equal, so the vertical equations give equal fall times.'},
 {q:'For u = 20.0 m/s at 60° above horizontal, uₓ is…',o:['17.3 m/s','20.0 m/s','10.0 m/s','0 m/s'],a:2,explain:'The horizontal side is adjacent to the stated angle: uₓ = u cos 60° = 10.0 m/s.'},
 {q:'At the apex of an angled launch…',o:['all velocity is zero','vᵧ = 0, vₓ remains nonzero and aᵧ = −g','gravity is zero','the ball has no kinetic energy'],a:1,explain:'The vertical direction reverses at the apex, but horizontal motion continues and gravity still accelerates the ball downward.'},
 {q:'A horizontal launch drops 19.6 m on Earth (g = 9.8 m/s²). Its fall time is…',o:['4.00 s','2.00 s','19.6 s','1.00 s'],a:1,explain:'19.6 = ½(9.8)t² gives t² = 4.00 s² and the positive root t = 2.00 s.'},
 {q:'That ball travels 30.0 m horizontally in 2.00 s. Its horizontal speed is…',o:['60.0 m/s','15.0 m/s','30.0 m/s','0.667 m/s'],a:1,explain:'uₓ = Δx/t = 30.0/2.00 = 15.0 m/s. Distance divided by time has velocity units.'},
 {q:'With up positive, a landing 4.90 m below launch has Δy =…',o:['+4.90 m','0 m','−4.90 m','−9.80 m/s²'],a:2,explain:'The displacement is below the launch origin and therefore negative. −9.80 m/s² describes acceleration, not displacement.'},
 {q:'When air resistance is important, which assumption needs rechecking?',o:['that x and y share the same elapsed time','that horizontal acceleration is zero','that a diagram needs labels','that a time must have a unit'],a:1,explain:'Drag can produce a horizontal resultant force and change vₓ. Both directions still describe the same elapsed time.'},
 {q:'The shortcut T = 2uᵧ/g requires…',o:['any launch and landing heights','a horizontal launch from any cliff','equal launch and landing heights with constant g','g = 0'],a:2,explain:'It comes from setting the later-event vertical displacement to zero. Unequal heights require the actual signed Δy.'}
];
let uid='',memory=null;
const oldSet=window.PhysicsFocused?.setAccount;
if(oldSet)window.PhysicsFocused.setAccount=function(account){oldSet.call(this,account);uid=String(account||'');memory=null;};
function state(){if(memory)return memory;try{memory=uid?JSON.parse(localStorage.getItem('physics-pilot:'+uid+':'+ID)||'null'):null;}catch{}if(!memory||typeof memory!=='object'||!memory.answers||typeof memory.answers!=='object'||Array.isArray(memory.answers))memory={index:0,answers:{}};return memory;}
function save(){if(!uid)return;try{localStorage.setItem('physics-pilot:'+uid+':'+ID,JSON.stringify(state()));}catch{}}
function answerKey(root,key){return (root.dataset.ppPage||'check')+':'+key;}
function wire(root){
 root.onclick=event=>{const trigger=event.target.closest?.('[data-pp-zoom]');if(!trigger)return;const source=trigger.closest('figure').querySelector('svg');const dialog=document.createElement('dialog');dialog.className='pp-diagram-dialog';const prefix='pp-zoom-'+(++graphic);dialog.innerHTML='<header><b>Read the labelled diagram</b><button type="button" class="pp-button pp-secondary">Close</button></header><p>On a small screen, swipe the diagram sideways to read every label.</p><div class="pp-dialog-scene">'+source.outerHTML.replace(/pp-arrow-(\d+)/g,prefix+'-$1')+'</div>';document.body.appendChild(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();};

 root.querySelectorAll('[data-pp-draft]').forEach(field=>{const key=answerKey(root,'draft:'+field.dataset.ppDraft);field.value=state().answers[key]||'';field.addEventListener('input',()=>{state().answers[key]=field.value;save();});});
 root.querySelectorAll('[data-pp-choice]').forEach(q=>{const key=answerKey(root,'choice:'+q.dataset.ppChoice);const stored=state().answers[key];q.querySelectorAll('input').forEach(i=>{i.checked=stored!==undefined&&String(i.value)===String(stored);i.addEventListener('change',()=>{state().answers[key]=i.value;save();});});q.querySelector('[data-pp-check]').onclick=()=>{const selected=q.querySelector('input:checked'),out=q.querySelector('.pp-feedback');if(!selected){out.textContent='Choose an explanation first.';return;}const right=Number(selected.value)===Number(q.dataset.correct);out.className='pp-feedback '+(right?'right':'review');out.textContent=(right?'Correct. ':'Reconsider this: ')+(q.querySelector('[data-reason="'+selected.value+'"]')?.innerHTML||'');};});
 root.querySelectorAll('[data-pp-number]').forEach(q=>{const field=q.querySelector('input'),key=answerKey(root,'number:'+q.dataset.ppNumber);field.value=state().answers[key]??'';field.addEventListener('input',()=>{state().answers[key]=field.value;save();});q.querySelector('[data-pp-number-check]').onclick=()=>{const out=q.querySelector('.pp-feedback');if(field.value.trim()===''){out.textContent='Enter a value first. Keep the shown unit.';return;}const value=Number(field.value),right=Number.isFinite(value)&&Math.abs(value-Number(q.dataset.answer))<=Number(q.dataset.tolerance);out.className='pp-feedback '+(right?'right':'review');out.textContent=right?'Correct. '+q.querySelector('template').innerHTML:'Check the component, signs and calculator brackets. Open the working hint if needed.';if(!right&&!q.querySelector('.pp-number-hint')){const help=document.createElement('details');help.className='pp-number-hint pp-reveal';help.innerHTML='<summary>Show a specific working hint</summary><p>'+q.querySelector('template').innerHTML+'</p>';q.append(help);}};});
 root.querySelectorAll('[data-pp-drop]').forEach(q=>{const input=q.querySelector('input');input.oninput=()=>{q.querySelector('[data-pp-drop-scene]').innerHTML=dropScene(Number(input.value));};});
 root.querySelectorAll('[data-pp-sim]').forEach(q=>{
  const mode=q.dataset.ppSim;const controls=[...q.querySelectorAll('input,select')];
  function update(){const u=mode==='launch'?Number(q.querySelector('[data-pp-u]').value):20,angle=mode==='launch'?Number(q.querySelector('[data-pp-angle]').value):0,g=mode==='launch'?G:Number(q.querySelector('[data-pp-g]').value),height=mode==='launch'?0:15;
   const f=flight(u,angle,g,height),p=Number(q.querySelector('[data-pp-time]').value)/100,t=f.time*p,point=f.at(t),scale=Math.min(470/Math.max(f.range,1),230/Math.max(f.peak+height,1)),ox=85,oy=300-height*scale;
   let body=line(65,300,705,300)+'<path d="'+curve(f,x=>ox+x*scale,y=>oy-y*scale)+'" stroke="#b3c7d1" stroke-width="3" stroke-dasharray="7 6" fill="none"/>';
   const x=ox+point.x*scale,y=oy-point.y*scale;
   body+=ball(x,y,12)+arrow(x+15,y,x+15+Math.min(110,f.ux*5),y,'#0b8774');if(Math.abs(point.vy)>.05)body+=arrow(x,y,x,y-Math.max(-60,Math.min(60,point.vy*8)),'#2a6bb2');
   body+=text(75,35,'Velocity: green = horizontal, blue = vertical')+text(75,395,'Equal x/y scales. Velocity arrows indicate direction, not a distance.');q.querySelector('[data-pp-scene]').innerHTML=svg('Calculated projectile position and horizontal and vertical velocity directions',body,430);
   q.querySelector('[data-pp-time-label]').textContent=t.toFixed(2)+' s';if(mode==='launch'){q.querySelector('[data-pp-u-label]').textContent=u.toFixed(0)+' m/s';q.querySelector('[data-pp-angle-label]').textContent=angle+'°';}
   q.querySelector('.pp-sim-readout').innerHTML='<span><b>x</b> '+point.x.toFixed(2)+' m</span><span><b>Δy</b> '+point.y.toFixed(2)+' m</span><span><b>vₓ</b> '+point.vx.toFixed(2)+' m/s</span><span><b>vᵧ</b> '+point.vy.toFixed(2)+' m/s</span><span><b>Flight time</b> '+f.time.toFixed(2)+' s</span><span><b>Range</b> '+f.range.toFixed(2)+' m</span>';
  }controls.forEach(i=>i.addEventListener('input',update));update();
 });
}
const chapters=[['Discover','What bends a ball’s path?'],['Build the launch','Resolve one velocity into two components'],['Use the model','Position, velocity and acceleration'],['Solve an exam','The Moon shot, explained'],['Apply it','Guided work, independent work and transfer']];
function worksheet(withKey=false){const section=(heading,q,solution)=>'<section><h2>'+heading+'</h2><p>'+q+'</p>'+(withKey?solution:'<div class="writing"></div>')+'</section>';return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Projectile motion practice'+(withKey?' — worked key':'')+'</title><style>@page{size:A4;margin:18mm}body{font:12pt/1.6 Arial;color:#18374d}h1{font-size:21pt}h2{font-size:16pt;break-after:avoid}section{break-inside:avoid;margin:25px 0}.writing{height:230px;background:repeating-linear-gradient(white,white 29px,#bbc8d1 30px)}table{width:100%;border-collapse:collapse}td,th{border:1px solid #8d9ca8;padding:8px;text-align:left}.pp-equation{font-size:16pt;padding:10px;border:1px solid #ddd}small{display:block;font-size:11pt}li{margin:9px 0}button{display:none}</style></head><body><h1>Projectile motion: from launch to landing</h1><p>Name: _______________________ Date: ______________</p><p>Use g = 9.80 m/s². Show a labelled diagram, equations, substitutions, units and interpretation. +x right; +y up.</p>'+section('1 · Horizontal launch [5 marks]','A ball launches horizontally and lands 19.6 m below launch, 30.0 m away horizontally. Calculate the flight time and launch speed.', '<ol><li>Δy = −19.6 m, uᵧ = 0, aᵧ = −9.80 m/s². [1]</li><li>Δy = uᵧt + ½aᵧt². [1]</li><li>−19.6 = −4.90t² → t = 2.00 s. [1]</li><li>uₓ = Δx/t. [1]</li><li>uₓ = 15.0 m/s to the right. [1]</li></ol>')+section('2 · Angled launch [6 marks]','A ball launches at 20.0 m/s, 60.0° above horizontal. Find Δx, Δy and vᵧ at 0.500 s.', '<ol><li>uₓ = 20 cos60° = 10.0 m/s; uᵧ = 20 sin60° = 17.3205… m/s. [1]</li><li>Δx = uₓt. [1]</li><li>Δx = 5.00 m. [1]</li><li>Δy = uᵧt − ½gt² with consistent substitution. [1]</li><li>Δy = +7.44 m. [1]</li><li>vᵧ = uᵧ − gt = +12.4 m/s, upward. [1]</li></ol>')+section('3 · The hoop challenge [4 marks]','A ball launches at 10.0 m/s, 30.0° above horizontal. The hoop is 8.00 m right and 2.00 m above launch. Calculate the ball’s vertical displacement at the hoop’s horizontal position and decide whether this ideal shot reaches it.', '<ol><li>uₓ = 8.66025… m/s and uᵧ = 5.00 m/s. [1]</li><li>t = 8.00/uₓ = 0.923760… s. [1]</li><li>Δy = (5.00)t − 4.90t² = +0.437 m. [1]</li><li>The ball is below the required +2.00 m, so the shot is too low. [1]</li></ol>')+'<p>Original practice questions and suggested worked guide — Learning Vault WA.</p></body></html>';}
function printWorksheet(withKey=false){return worksheet(withKey).replace(/<ol>([\s\S]*?)<\/ol>/g,(_,items)=>'<table><thead><tr><th>Expected working / reasoning</th><th>Marks</th></tr></thead><tbody>'+[...items.matchAll(/<li>([\s\S]*?)<\/li>/g)].map(m=>'<tr><td>'+m[1].replace(/\s*\[\d+\]/g,'')+'</td><td>'+(m[1].match(/\[(\d+)\]/)?.[1]||'')+'</td></tr>').join('')+'</tbody></table>');}
function mount(topic,host){document.body.classList.add('senior-lms-open');let current=Math.min(pages.length-1,Math.max(0,Math.trunc(Number(state().index))||0)),master=false;
 host.innerHTML='<div class="pp-tools"><span class="pp-pilot-label">INTERACTIVE PHYSICS</span><button type="button" class="pp-button pp-secondary" data-pp-print>Print practice</button><button type="button" class="pp-button pp-secondary" data-pp-print-key>Print worked key</button></div><div class="sv-lms pp-lms"><aside class="sv-course"><span class="sv-course-title">YEAR 12 · PHYSICS</span><h3>Projectile motion</h3><p class="pp-course-description">From launch to landing</p><div id="y12List"></div></aside><section class="sv-stage"><div class="sv-top"><div><span id="y12Step"></span><h2 id="y12Title"></h2></div><span id="y12Pct" class="pp-section-badge"></span></div><div class="sv-progress"><i id="y12Bar"></i></div><article id="y12Screen" class="sv-screen"></article><div class="sv-actions"><button id="y12Prev" class="pp-button pp-secondary">← Previous</button><button id="y12Next" class="pp-button">Continue →</button></div></section></div>';
 const list=host.querySelector('#y12List'),screen=host.querySelector('#y12Screen'),title=host.querySelector('#y12Title'),step=host.querySelector('#y12Step'),badge=host.querySelector('#y12Pct'),bar=host.querySelector('#y12Bar'),prev=host.querySelector('#y12Prev'),next=host.querySelector('#y12Next');
 function go(n){master=false;current=n;state().index=n;save();render();}
 function nav(){list.innerHTML=chapters.map(([label,subtitle],chapter)=>'<details class="pp-chapter" '+(!master&&pages[current].chapter===chapter?'open':'')+'><summary><span>'+String(chapter+1).padStart(2,'0')+'</span><b>'+label+'</b></summary><p>'+subtitle+'</p>'+pages.map((p,i)=>p.chapter===chapter?'<button type="button" class="sv-lesson-item '+(!master&&current===i?'active':'')+'" data-i="'+i+'"><b>'+String(i+1)+'</b><span>'+esc(p.title)+'</span></button>':'').join('')+'</details>').join('')+'<button type="button" class="pp-master-nav '+(master?'active':'')+'" id="y12Master">Check understanding · 10 questions</button><label class="pp-mobile-nav">Jump to a section<select data-pp-jump>'+chapters.map(([label],c)=>'<optgroup label="'+label+'">'+pages.map((p,i)=>p.chapter===c?'<option value="'+i+'" '+(!master&&i===current?'selected':'')+'>'+String(i+1).padStart(2,'0')+' · '+esc(p.title)+'</option>':'').join('')+'</optgroup>').join('')+'<option value="master" '+(master?'selected':'')+'>Check understanding</option></select></label>';
  list.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>go(Number(b.dataset.i)));list.querySelector('#y12Master').onclick=showMaster;list.querySelector('[data-pp-jump]').onchange=e=>e.target.value==='master'?showMaster():go(Number(e.target.value));
 }
 function render(){const p=pages[current];title.textContent=p.title;step.textContent='Section '+(current+1)+' of '+pages.length;badge.textContent=chapters[p.chapter][0];bar.style.width=Math.round((current+1)/pages.length*100)+'%';screen.dataset.ppPage=String(current);screen.innerHTML=p.html;wire(screen);prev.disabled=current===0;next.hidden=false;next.textContent=current===pages.length-1?'Check understanding →':'Continue →';nav();}
 function showMaster(){master=true;title.textContent='Check understanding';step.textContent='10 questions · review the reasoning';badge.textContent='Concept check';bar.style.width='100%';screen.dataset.ppPage='master';screen.innerHTML='<div class="pp-page"><p>Answer before checking. You can use the feedback to revisit the relevant idea.</p><div class="pp-master-questions">'+bank.map((q,i)=>'<fieldset data-pp-master-q="'+i+'"><legend>'+String(i+1)+'. '+esc(q.q)+'</legend>'+q.o.map((o,j)=>'<label><input type="radio" name="pp-master-'+i+'" value="'+j+'"> '+esc(o)+'</label>').join('')+'<p class="pp-feedback" role="status"></p></fieldset>').join('')+'</div><button type="button" class="pp-button" data-pp-mark-master>Check all answers</button><p class="pp-master-result" role="status" aria-live="polite"></p><button class="pp-button pp-secondary" type="button" data-pp-review>Return to the reference</button></div>';screen.querySelector('[data-pp-mark-master]').onclick=()=>{let correct=0;screen.querySelectorAll('[data-pp-master-q]').forEach(f=>{const q=bank[Number(f.dataset.ppMasterQ)],selected=f.querySelector('input:checked'),ok=selected&&Number(selected.value)===q.a;if(ok)correct++;const out=f.querySelector('.pp-feedback');out.className='pp-feedback '+(ok?'right':'review');out.textContent=(ok?'Correct. ':selected?'Review: ':'No answer selected. ')+q.explain;});screen.querySelector('.pp-master-result').textContent=correct===bank.length?'10/10 concepts correct. Now check that your written solutions explain the method.':correct+'/10 concepts correct. Read the explanations, revise your choices and check again.';};screen.querySelector('[data-pp-review]').onclick=()=>go(pages.length-1);prev.disabled=false;next.hidden=true;nav();}
 prev.onclick=()=>master?go(pages.length-1):current>0&&go(current-1);next.onclick=()=>current===pages.length-1?showMaster():go(current+1);
 for(const [selector,key]of [['[data-pp-print]',false],['[data-pp-print-key]',true]])host.querySelector(selector).onclick=()=>{const w=window.open('','_blank');if(!w)return;w.document.open();w.document.write(printWorksheet(key));w.document.close();w.focus();w.print();};render();
}
const newTitle='Projectile motion: from launch to landing';
existing.title=newTitle;existing.screens=pages;existing.bank=bank;existing.wire=wire;existing.pilotVersion=VERSION;
const entry=window.PhysicsFocused?.lessons.find(e=>e.id===ID);if(entry){entry.title=newTitle;entry.subtitle=pages.length+' sections · explore motion · solve a real exam · practise independently';}
for(const groups of Object.values(window.PhysicsFocused?.sequences?.[12]||{}))for(const group of groups){const tile=group.lessons.find(t=>t.id===ID);if(tile){tile.title=newTitle;tile.subtitle=entry.subtitle;}}
const oldBuild=window.Year12PhysicsPlayer.build;window.Year12PhysicsPlayer.build=(topic,host)=>topic.id===ID?mount(topic,host):oldBuild(topic,host);
for(const audit of [window.PhysicsExplicitDepth?.audit,window.PhysicsVisualRefresh?.audit]){const row=audit?.find(e=>e.id===ID);if(row){row.slides=pages.length;if('worked'in row)row.worked=pages.filter(p=>p.type==='worked').length;if('diagrams'in row)row.diagrams=pages.filter(p=>p.html.includes('<svg')||p.html.includes('data-pp-sim')).length;if('pictures'in row)row.pictures=pages.filter(p=>p.html.includes('<img')).length;}}
window.PhysicsProjectilePilot={id:ID,version:VERSION,pages,bank,flight,worksheet:printWorksheet,figures:{components,forces,axes,snapshots,dropScene,xMotion,apex,yTerms,cliff,compareAngles},mount};
})();
